	@Test
	void collisionWinnerAndResizeReuseExistingWeakObject() throws Exception {
		Map<Integer, Long> first = new HashMap<>();
		long left = 0, right = 0;
		for (long id = 1; right == 0; id++) {
			Long old = first.putIfAbsent(slot(id, 4096), id);
			if (old != null) {
				left = old;
				right = id;
			}
		}
		var memo = new NativeValueMemo(source(), null);
		Value loser = memo.value(left, 1), winner = memo.value(right, 1);
		var reference = memo.references[slot(right, 4096)];
		assertSame(winner, memo.value(right, 1));
		assertTrue(resize(memo, 8192));
		assertSame(reference, memo.references[slot(right, 8192)]);
		assertSame(winner, memo.value(right, 1));
		assertNotSame(loser, memo.value(left, 1));
		memo.clear();
	}

