	@Test
	void growthRetainsFullOldAndNewReservationUntilSwap() throws Exception {
		var account = new Account(Long.MAX_VALUE);
		var memo = new NativeValueMemo(source(), account);
		Value retained = memo.value(1, 1);
		long oldCharge = 64 + 4096L * 72, newCharge = 64 + 8192L * 72;
		assertEquals(oldCharge, account.used);
		assertTrue(resize(memo, 8192));
		assertEquals(oldCharge + newCharge, account.peak);
		assertEquals(newCharge, account.used);
		assertSame(retained, memo.value(1, 1));
		memo.clear();
		memo.clear();
		assertEquals(0, account.used);
	}

