	@Test
	void hitProbeRunsAfterCountersAndPreservesStrongReturnValue() {
		boolean probeEnabled = Boolean.getBoolean("rdf4j.lmdb.nativeValueMemo.testProbe");
		var memo = new NativeValueMemo(source(), null);
		Value original = memo.value(7, 1);
		var old = NativeValueMemo.testHitObserver;
		var calls = new AtomicInteger();
		try {
			NativeValueMemo.testHitObserver = seen -> {
				assertSame(memo, seen);
				assertEquals(2, seen.snapshot().probes());
				assertEquals(1, seen.snapshot().hits());
				for (var ref : seen.references)
					if (ref != null)
						ref.clear();
				calls.incrementAndGet();
			};
			assertSame(original, memo.value(7, 1));
			assertEquals(probeEnabled ? 1 : 0, calls.get());
			if (probeEnabled) {
				assertNotSame(original, memo.value(7, 1));
			} else {
				assertSame(original, memo.value(7, 1));
				assertEquals(0, calls.get());
			}
		} finally {
			NativeValueMemo.testHitObserver = old;
			memo.clear();
		}
	}

	private static final class Account implements KernelRuntime.MemoryAccount {
		final long limit;
		long used, peak;

		Account(long limit) {
			this.limit = limit;
		}

		public boolean tryReserve(long n) {
			if (n > limit - used)
				return false;
			used += n;
			peak = Math.max(peak, used);
			return true;
		}

		public void release(long n) {
			used -= n;
			assertTrue(used >= 0);
		}
	}
